import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.DGu13UIe.js";const d="/bagent/lessons/49-str-replace/image.png",g=JSON.parse('{"title":"第 49 课 · str_replace 局部修改","description":"","frontmatter":{"editLink":"https://github.com/SyncLionPaw/bagent/edit/main/lessons/49-str-replace/doc.md"},"headers":[],"relativePath":"chapters/49-str-replace.md","filePath":"chapters/49-str-replace.md"}'),o={name:"chapters/49-str-replace.md"};function r(l,e,c,n,h,p){return s(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="第-49-课-·-str-replace-局部修改" tabindex="-1">第 49 课 · str_replace 局部修改 <a class="header-anchor" href="#第-49-课-·-str-replace-局部修改" aria-label="Permalink to &quot;第 49 课 · str_replace 局部修改&quot;">​</a></h1><p><strong>约 20 分钟</strong> · <a href="/bagent/chapters/48-read-lines.html">第 48 课</a> 之后 · <strong>独立插件</strong></p><p><a href="/bagent/chapters/43-write-file.html">第 43 课</a> 的 <code>write_file</code> 会<strong>整文件覆盖</strong>——改一行也要把全文塞进 <code>content</code>，大文件易出错、diff 难读。第 48 课起 <code>read_file</code> 带行号，模型能精确定位，但写入仍只有「全量覆盖」一种方式。</p><p>本课在 <a href="/bagent/chapters/48-read-lines.html">第 48 课</a> 之上增加 <strong><code>str_replace</code></strong>：按 <strong>exact match</strong> 搜索替换，只改匹配片段；路径限制与审批策略与 <code>write_file</code> 相同。</p><p><img src="'+d+'" alt="用两次 str_replace 改 CSS 与 innerHTML 模板，日期与标题同行"></p><p>上图是一次真实改动：<code>timeline.html</code> 里卡片日期与标题原先上下两行，只需动 <strong>两段</strong> 连续原文——一段 CSS（<code>.card .date</code> → <code>.card-header</code> 的 flex 布局）、一段 JS 模板字符串里的 <code>innerHTML</code>。两次 <code>str_replace</code> 各替换一处，<strong>不必</strong>用 <code>write_file</code> 重写整份 HTML；左侧预览立刻变成日期与标题同一行、卡片更矮。这正是局部修改的优势：<strong>diff 小、上下文少、大文件也安全</strong>。</p><hr><h2 id="_1-何时用-str-replace-vs-write-file" tabindex="-1">1. 何时用 str_replace vs write_file <a class="header-anchor" href="#_1-何时用-str-replace-vs-write-file" aria-label="Permalink to &quot;1. 何时用 str_replace vs write_file&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>推荐工具</th></tr></thead><tbody><tr><td>改函数名、修 typo、删一行</td><td><code>str_replace</code></td></tr><tr><td>新建小文件、整文件重写</td><td><code>write_file</code></td></tr><tr><td>不确定原文长什么样</td><td>先 <code>read_file</code>，再 <code>str_replace</code></td></tr></tbody></table><p><code>str_replace</code> 不做模糊匹配：空格、缩进、换行须与文件<strong>完全一致</strong>。行号输出里的 <code> 12|</code> 前缀<strong>不能</strong>写进 <code>old_string</code>——只复制 <code>|</code> 右侧正文。</p><hr><h2 id="_2-参数与行为" tabindex="-1">2. 参数与行为 <a class="header-anchor" href="#_2-参数与行为" aria-label="Permalink to &quot;2. 参数与行为&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>作用</th></tr></thead><tbody><tr><td><code>path</code></td><td>绝对路径（必填）；须在 cwd 下，禁止 <code>.git</code>、<code>node_modules</code>、<code>.env</code></td></tr><tr><td><code>old_string</code></td><td>要查找的原文（必填，非空）</td></tr><tr><td><code>new_string</code></td><td>替换文本（必填，可为 <code>&quot;&quot;</code> 表示删除）</td></tr><tr><td><code>replace_all</code></td><td>可选，默认 <code>false</code>；<code>true</code> 时替换所有匹配</td></tr></tbody></table><p>行为要点：</p><ul><li>只处理 <strong>UTF-8 纯文本</strong>；二进制或非文本类型（PDF、图片等）返回错误</li><li><strong>0 次匹配</strong> → 明确报错，提示用 <code>read_file</code> 核对</li><li><strong>多次匹配且 <code>replace_all=false</code></strong> → 报错，要求唯一或设 <code>replace_all=true</code></li><li><strong>成功</strong> → 写回文件，返回 <code>{ ok: true, path, replacements, bytes }</code></li><li><strong>须用户审批</strong>（与 <code>write_file</code> 相同；侧栏红色 danger 框）</li></ul><p>示例：把 <code>hello</code> 改成 <code>world</code>（文件中仅一处）：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/abs/path/foo.ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;old_string&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;hello&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;new_string&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;world&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>成功返回：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/abs/path/foo.ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;replacements&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;bytes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1284</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><hr><h2 id="_3-代码位置" tabindex="-1">3. 代码位置 <a class="header-anchor" href="#_3-代码位置" aria-label="Permalink to &quot;3. 代码位置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>作用</th></tr></thead><tbody><tr><td><code>agent/strReplace.ts</code></td><td><code>runStrReplace()</code>：读文件、计数匹配、写回</td></tr><tr><td><code>agent/tools.ts</code></td><td><code>strReplaceBefore</code> 校验、<code>toolHooks</code>、工具定义、<code>runTool</code> 分支</td></tr><tr><td><code>agent/system.ts</code></td><td>提示小改动用 <code>str_replace</code>、须审批</td></tr><tr><td><code>src/sidebar.ts</code></td><td><code>str_replace</code> 审批框 danger 样式</td></tr></tbody></table><p>第 48 课的行号 <code>read_file</code>、截断翻页、对话保存等<strong>全部保留</strong>，本课只增量 <code>str_replace</code>。</p><hr><h2 id="_4-动手" tabindex="-1">4. 动手 <a class="header-anchor" href="#_4-动手" aria-label="Permalink to &quot;4. 动手&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ch49:compile</span></span></code></pre></div><ol><li>打开 <strong><code>lessons/49-str-replace</code></strong> → <strong>F5</strong></li><li>让 Agent 在 cwd 下创建 <code>demo.txt</code>，写入两行文本</li><li>再让 Agent 用 <code>str_replace</code> 改其中一行 → 侧栏应出现<strong>红色</strong>审批框</li><li>允许后 <code>read_file</code> 确认只改了目标片段；其余行不变</li></ol><p>终端调试：<code>npm run ch49</code>（审批时终端会提示「将修改文件内容」）。</p><hr><h2 id="检查点" tabindex="-1">检查点 <a class="header-anchor" href="#检查点" aria-label="Permalink to &quot;检查点&quot;">​</a></h2><ul><li>[ ] <code>str_replace</code> 审批框为 danger 样式（与 <code>write_file</code> 一致）？</li><li>[ ] 0 匹配、多匹配未设 <code>replace_all</code> 时有清晰报错？</li><li>[ ] 成功返回含 <code>replacements</code> 与 <code>bytes</code>？</li><li>[ ] <code>read_file</code> 行号、<code>offset</code> 续读仍正常？</li><li>[ ] <code>/save</code>、<code>/load</code> 对话保存仍可用？</li></ul><hr><p><a href="/bagent/chapters/48-read-lines.html">← 第 48 课</a></p>',33)])])}const E=t(o,[["render",r]]);export{g as __pageData,E as default};
